namespace Quantum.Protocols {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;

    operation Teleport(msg : Qubit, alice : Qubit, bob : Qubit) : Unit {
        // Alice shares Bell pair with Bob
        H(alice);
        CNOT(alice, bob);

        // Bell measurement
        CNOT(msg, alice);
        H(msg);
        let (a, b) = (M(msg), M(alice));

        // Classical communication and correction
        if (b == One) { X(bob); }
        if (a == One) { Z(bob); }
    }
}
